"""TK-010 gate, step 1: label the 60 points of sample60 (TK-008) from the downloaded OSM tiles -> tk010/gate_labels.json.
Step 2: node tools/tk010_gate60.mjs (class A by PROTOCOL.md 2.1, hidden share, match with the TK-009 label)."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import tk010_areas as t

rows = json.load(open('C:/verger-data/pilot/tk008/area60_final.json', encoding='utf8'))
bb = t.stage_bbox()
def city_of(lat, lng):
    hit = [(( b[2] - b[0]) * (b[3] - b[1]), c) for c, b in bb.items() if b[0] <= lat <= b[2] and b[1] <= lng <= b[3]]
    return min(hit)[1] if hit else None

by_city = {}
for r in rows: by_city.setdefault(city_of(r['lat'], r['lng']), []).append(r)
out = {}
for city, rs in by_city.items():
    if city is None:
        for r in rs: out[r['i']] = {'city': None, 'tiles': 0, 'tiles_total': 0, 'label': ''}
        continue
    total = len(list(t.tiles(bb[city])))
    ready = sum(os.path.exists('%s%s_%d.json' % (t.RAW, t.slug(city), i)) for i in range(total))
    labels = t.label_points(city, t.city_polygons(city), [(r['lat'], r['lng']) for r in rs]) if ready else {}
    for k, r in enumerate(rs): out[r['i']] = {'city': city, 'tiles': ready, 'tiles_total': total, 'label': labels.get(k, '')}
json.dump(out, open(t.T + 'gate_labels.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
miss = {(v['city'], v['tiles'], v['tiles_total']) for v in out.values() if v['tiles'] < v['tiles_total']}
print('points', len(out), 'cities', len(by_city), 'incomplete city tiles', sorted(miss, key=str))
                    log('tile', city, i, len(j['elements']), 'objects', round(time.time() - t0, 1), 's', u.split('/')[2])
                    time.sleep(3); break
                except Exception as ex:
                    log('tile', city, i, 'retry in', wait, str(ex)[:80]); time.sleep(wait); wait = min(wait * 2, 300)

def polygons(els):
    """[(field, name, area_deg2, geometry)] from Overpass `out geom` elements, deduped by id."""
    from shapely.geometry import Polygon, LineString, MultiPolygon
    from shapely.ops import polygonize, unary_union
    from shapely import make_valid
    out, seen = [], set()
    for el in els:
        key = (el['type'], el['id'])
        if key in seen: continue
        seen.add(key)
        tg = el.get('tags', {}); name = (tg.get('name') or '').strip()
        field = tg.get('place') if tg.get('place') in FIELDS else ADMIN_FIELD.get(tg.get('admin_level', ''))
        if not name or not field: continue
        try:
            if el['type'] == 'way':
